<script setup>
import { ref,computed,watch,onBeforeUnmount } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { api,notify,speak } from '../api'
import Icon from '../components/Icon.vue'
import '../sentences.css'
const route=useRoute(),router=useRouter()
const sections=[['today','Học hôm nay'],['library','Kho câu'],['lessons','90 buổi học'],['progress','Tiến độ']]
const tab=computed(()=>sections.some(s=>s[0]===route.query.tab) ? route.query.tab : 'today')
const meta=ref(null),stats=ref(null),lessons=ref([]),error=ref(''),initialLoading=ref(true),savingGoal=ref(false)
const query=ref(''),topic=ref(''),level=ref(''),context=ref(''),lesson=ref(route.query.lesson||''),status=ref('all'),page=ref(1)
const items=ref([]),total=ref(0),loading=ref(false),libraryError=ref(''),lessonSearch=ref(''),noteRow=ref(null),noteText=ref(''),savingNote=ref(false)
let timer,revision=0
const filteredLessons=computed(()=>lessons.value.filter(l=>`${l.lesson} ${l.topics} ${l.levels}`.toLocaleLowerCase('vi').includes(lessonSearch.value.toLocaleLowerCase('vi'))))
const nextLesson=computed(()=>lessons.value.find(l=>l.learned<l.total))
const pct=computed(()=>stats.value ? Math.min(100,Math.round(stats.value.today_new/stats.value.daily_goal*100)) : 0)
const maxActivity=computed(()=>Math.max(5,...(stats.value?.activity||[]).map(d=>d.sentences)))
function learn(training='study',extra={}){return {path:'/sentences/learn',query:{training,...extra}}}
async function initialize(){initialLoading.value=true;error.value='';try{[meta.value,stats.value,lessons.value]=await Promise.all([api('/sentences/meta'),api('/sentences/stats'),api('/sentences/lessons')]);if(tab.value==='library')await load()}catch(e){error.value=e.message}finally{initialLoading.value=false}}
async function load(){const version=++revision;loading.value=true;libraryError.value='';try{const params=new URLSearchParams({q:query.value,topic:topic.value,level:level.value,context:context.value,status:status.value,page:page.value});if(lesson.value)params.set('lesson',lesson.value);const result=await api('/sentences?'+params);if(version===revision){items.value=result.items;total.value=result.total}}catch(e){if(version===revision)libraryError.value=e.message}finally{if(version===revision)loading.value=false}}
watch([query,topic,level,context,lesson,status],()=>{page.value=1;clearTimeout(timer);revision++;timer=setTimeout(load,200)})
watch(page,load)
watch(tab,t=>{if(t==='library' && meta.value)load()})
watch(()=>route.query.lesson,value=>lesson.value=value||'')
onBeforeUnmount(()=>{clearTimeout(timer);revision++})
async function setGoal(value){savingGoal.value=true;try{await api('/sentences/settings',{method:'PATCH',body:JSON.stringify({daily_goal:value})});meta.value.daily_goal=value;stats.value.daily_goal=value;notify(`Đã đặt mục tiêu ${value} câu mới mỗi ngày`)}catch(e){notify(e.message)}finally{savingGoal.value=false}}
async function saveBookmark(row){if(row.pending)return;row.pending=true;try{const updated=await api(`/sentences/${row.id}/note`,{method:'PUT',body:JSON.stringify({saved:!row.saved})});row.saved=updated.saved;if(status.value==='saved')await load();notify(updated.saved?'Đã lưu câu giao tiếp':'Đã bỏ lưu câu')}catch(e){notify(e.message)}finally{row.pending=false}}
function editNote(row){noteRow.value=row;noteText.value=row.note}
async function saveNote(){savingNote.value=true;try{const updated=await api(`/sentences/${noteRow.value.id}/note`,{method:'PUT',body:JSON.stringify({note:noteText.value})});noteRow.value.note=updated.note;noteRow.value=null;notify('Đã lưu ghi chú của anh')}catch(e){notify(e.message)}finally{savingNote.value=false}}
function clearFilters(){query.value='';topic.value='';level.value='';context.value='';lesson.value='';status.value='all'}
initialize()
</script>
<template>
<div class="page sentences-page">
  <div class="page-heading"><div><div class="eyebrow">NGHE ĐƯỢC · NÓI ĐƯỢC · ĐÁP LẠI ĐƯỢC</div><h1>900 câu giao tiếp</h1><p>Học cả câu trong tình huống, rồi thử dùng theo cách của bạn.</p></div><RouterLink to="/sentences?tab=library" class="btn outline"><Icon name="Search" :size="17"/>Tra cứu câu</RouterLink></div>
  <nav class="sentence-tabs" aria-label="Các phần học câu"><RouterLink v-for="[value,label] in sections" :key="value" :to="{path:'/sentences',query:{tab:value}}" :class="{selected:tab===value}" :aria-current="tab===value ? 'page' : undefined">{{label}}</RouterLink></nav>
  <div v-if="error" class="error-panel" role="alert">{{error}}<button class="btn outline" @click="initialize">Thử lại</button></div>
  <div v-else-if="initialLoading" class="loading-panel">Đang chuẩn bị bộ câu giao tiếp…</div>
  <template v-else>
  <template v-if="tab==='today'">
    <section class="sentence-hero"><div><span class="hero-label">MỘT CUỘC TRÒ CHUYỆN, TỪNG CÂU MỘT</span><h2>Bắt đầu từ những điều<br>bạn muốn nói mỗi ngày.</h2><p>Ôn câu đến hạn trước, sau đó học {{stats.daily_goal}} câu mới. Lộ trình mặc định bắt đầu với A1–A2.</p><RouterLink :to="learn()" class="btn lime">{{stats.due ? 'Ôn & học hôm nay' : 'Bắt đầu học hôm nay'}}<Icon name="ArrowRight" :size="18"/></RouterLink></div><div class="sentence-hero-dialog" aria-hidden="true"><span class="dialog-label">A LITTLE CONVERSATION</span><div class="dialog-bubble">How's it going?<small>Dạo này thế nào?</small></div><div class="dialog-bubble reply">It's going well, thanks!<small>Mọi chuyện đều ổn, cảm ơn nhé!</small></div><span class="dialog-caption"><Icon name="MessagesSquare" :size="16"/>Nghe một câu. Bắt đầu kết nối.</span></div></section>
    <div class="sentence-kpis"><div><span class="stat-icon green"><Icon name="BookOpen"/></span><strong>{{stats.learned}}<small>/ {{meta.total}} câu đã học</small></strong></div><div><span class="stat-icon purple"><Icon name="Layers"/></span><strong>{{stats.due}}<small>câu đến lịch ôn</small></strong></div><div><span class="stat-icon orange"><Icon name="Flame"/></span><strong>{{stats.streak}}<small>ngày học câu liên tiếp</small></strong></div><div><span class="stat-icon blue"><Icon name="BadgeCheck"/></span><strong>{{stats.completed_lessons}}<small>/ 90 buổi đã học hết</small></strong></div></div>
    <div class="sentence-today-grid"><section class="sentence-panel"><div class="section-heading"><div><h2>Chọn cách luyện hôm nay</h2><p>Mỗi chế độ giúp bạn nhớ câu theo một cách.</p></div></div><div class="sentence-mode-list"><RouterLink :to="learn('study')"><span class="stat-icon green"><Icon name="Headphones"/></span><div><h3>Nghe & hiểu trong ngữ cảnh</h3><p>Nghe trước, xem nghĩa, nói theo rồi luyện đáp lại.</p></div><Icon name="ArrowRight" :size="18"/></RouterLink><RouterLink :to="learn('recall')"><span class="stat-icon purple"><Icon name="RotateCw"/></span><div><h3>Tự nhớ câu</h3><p>Nhìn tình huống và nghĩa, tự nói tiếng Anh trước khi xem.</p></div><Icon name="ArrowRight" :size="18"/></RouterLink><RouterLink :to="learn('response')"><span class="stat-icon blue"><Icon name="MessagesSquare"/></span><div><h3>Luyện phản xạ đáp lại</h3><p>Nghe người đối diện nói rồi thử trả lời thành tiếng.</p></div><Icon name="ArrowRight" :size="18"/></RouterLink></div><div class="sentence-next"><span>{{nextLesson ? `Buổi tiếp theo: ${nextLesson.lesson}` : 'Bạn đã học qua tất cả các buổi'}}</span><RouterLink to="/sentences?tab=lessons" class="text-link">Xem 90 buổi<Icon name="ArrowRight" :size="15"/></RouterLink></div></section><aside class="sentence-panel sentence-goal"><div class="eyebrow">NHỊP HỌC VỪA SỨC</div><h2>{{stats.today_new}} / {{stats.daily_goal}} câu mới hôm nay</h2><div class="progress-track"><span :style="{width:pct+'%'}"></span></div><p>{{stats.today_new>=stats.daily_goal ? 'Đã đạt mục tiêu câu mới. Bạn vẫn có thể ôn hoặc luyện theo buổi.' : `Còn ${stats.daily_goal-stats.today_new} câu mới để hoàn thành mục tiêu.`}}</p><div class="goal-switch" aria-label="Mục tiêu câu mới"><button v-for="n in [5,10]" :key="n" :disabled="savingGoal" :class="{selected:stats.daily_goal===n}" :aria-pressed="stats.daily_goal===n" @click="setGoal(n)">{{n}} câu / ngày</button></div><small>Mỗi câu mới chỉ tính một lần trong ngày. Câu ôn được theo dõi riêng.</small><RouterLink :to="learn('study',{mode:'due',level:''})" class="btn outline full">Ôn câu đến hạn<Icon name="ArrowRight" :size="16"/></RouterLink></aside></div>
    <div class="sentence-method"><strong>Khoảng 20 phút mỗi ngày</strong><span><b>01</b> Ôn câu cũ</span><span><b>02</b> Nghe & nói câu mới</span><span><b>03</b> Tự nhớ & đáp lại</span></div>
  </template>
  <template v-else-if="tab==='library'">
    <div class="sentence-library-filters"><label class="search-field"><Icon name="Search" :size="18"/><input v-model="query" aria-label="Tìm câu giao tiếp" placeholder="Tìm câu, nghĩa, tình huống hoặc mã câu…"/></label><select v-model="topic" aria-label="Chủ đề câu"><option value="">Tất cả chủ đề</option><option v-for="t in meta.topics" :key="t.name" :value="t.name">{{t.name}}</option></select><select v-model="level" aria-label="Trình độ câu"><option value="">Mọi trình độ</option><option value="basic">A1–A2 · Cơ bản</option><option v-for="l in meta.levels" :key="l.name" :value="l.name">{{l.name}}</option></select><select v-model="context" aria-label="Bối cảnh câu"><option value="">Mọi bối cảnh</option><option v-for="c in meta.contexts" :key="c">{{c}}</option></select><select v-model="lesson" aria-label="Buổi học câu"><option value="">Tất cả buổi</option><option v-for="l in lessons" :key="l.lesson" :value="String(l.lesson)">Buổi {{l.lesson}}</option></select></div>
    <div class="toolbar"><div class="tabs"><button v-for="[value,label] in [['all','Tất cả'],['new','Chưa học'],['learned','Đã học'],['due','Đến lịch ôn'],['saved','Đã lưu'],['mastered','Nhớ vững']]" :key="value" :class="{selected:status===value}" @click="status=value">{{label}}</button></div><span class="result-count">{{total}} mục câu</span></div>
    <div v-if="libraryError" class="error-panel" role="alert">{{libraryError}}<button class="btn outline" @click="load">Thử lại</button></div><div v-else-if="loading" class="loading-panel">Đang tìm câu…</div><div v-else-if="!items.length" class="empty-state"><Icon name="SearchX" :size="36"/><h3>Chưa có câu phù hợp</h3><p>Thử đổi bộ lọc hoặc tìm bằng từ khác.</p><button class="btn outline" @click="clearFilters">Xóa bộ lọc</button></div>
    <div v-else class="sentence-list"><article v-for="row in items" :key="row.id" class="sentence-row"><div class="sentence-row-heading"><div class="sentence-tags"><span class="level">{{row.level}}</span><span>{{row.id}}</span><span>Buổi {{row.lesson}}</span><span>{{row.topic}}</span></div><button class="icon-button" :class="{saved:row.saved}" :disabled="row.pending" :aria-pressed="!!row.saved" :aria-label="(row.saved?'Bỏ lưu câu ':'Lưu câu ')+row.id" @click="saveBookmark(row)"><Icon name="Bookmark" :size="19"/></button></div><div class="sentence-row-english"><h3>{{row.english}}</h3><button class="icon-button" :aria-label="'Nghe câu '+row.id" @click="speak(row.english)"><Icon name="Volume2" :size="20"/></button></div><p class="sentence-meaning">{{row.vietnamese}}</p><div class="sentence-context"><Icon name="MapPin" :size="14"/>{{row.situation}}<span>·</span>{{row.context}}</div><details class="sentence-reply"><summary>Xem cách đáp lại</summary><div><p>{{row.reply_english}}<button class="icon-button" :aria-label="'Nghe đáp lại '+row.id" @click="speak(row.reply_english)"><Icon name="Volume2" :size="17"/></button></p><small>{{row.reply_vietnamese}}</small></div></details><p v-if="row.note" class="sentence-user-note">Ghi chú: {{row.note}}</p><div class="sentence-row-footer"><span :class="['word-status',row.last_rating?'learned':'']"><span></span>{{row.stage>=4 && row.interval_days>=14 ? 'Đã nhớ vững' : row.last_rating ? 'Đang ôn' : 'Chưa học'}}</span><div><button class="text-link" @click="editNote(row)"><Icon name="Plus" :size="14"/>{{row.note?'Sửa ghi chú':'Ghi chú'}}</button><RouterLink :to="learn('study',{mode:'single',sentence:row.id})" class="btn outline">Luyện câu này<Icon name="ArrowRight" :size="15"/></RouterLink></div></div></article></div>
    <div v-if="total>15" class="pagination"><button class="btn outline" :disabled="page<=1||loading" @click="page--"><Icon name="ChevronLeft" :size="16"/>Trước</button><span>{{page}} / {{Math.ceil(total/15)}}</span><button class="btn outline" :disabled="page>=Math.ceil(total/15)||loading" @click="page++">Sau<Icon name="ChevronRight" :size="16"/></button></div>
  </template>
  <template v-else-if="tab==='lessons'"><div class="section-heading sentence-lesson-heading"><div><h2>90 buổi, từng bước một</h2><p>Mỗi buổi có 10 câu theo thứ tự trong file. Bạn có thể học 5 câu rồi quay lại học tiếp.</p></div><label class="search-field"><Icon name="Search" :size="17"/><input v-model="lessonSearch" aria-label="Tìm buổi học" placeholder="Số buổi, chủ đề, trình độ…"/></label></div><div class="lesson-grid"><article v-for="l in filteredLessons" :key="l.lesson" class="lesson-card"><div class="lesson-card-top"><span>BUỔI {{String(l.lesson).padStart(2,'0')}}</span><span class="level">{{l.levels.replaceAll(',', ' / ')}}</span></div><h3>{{l.topics.replaceAll(',', ' · ')}}</h3><div class="progress-track"><span :style="{width:l.learned/l.total*100+'%'}"></span></div><p>{{l.learned}} / {{l.total}} câu đã học<span v-if="l.due"> · {{l.due}} đến hạn</span></p><div><RouterLink :to="learn('study',{mode:'lesson',lesson:l.lesson,level:''})" class="text-link">{{l.learned===l.total ? 'Luyện lại buổi này' : l.learned ? 'Tiếp tục buổi' : 'Bắt đầu buổi'}}<Icon name="ArrowRight" :size="16"/></RouterLink><RouterLink :to="{path:'/sentences',query:{tab:'library',lesson:l.lesson}}" class="muted-link">Xem câu</RouterLink></div></article></div><div v-if="!filteredLessons.length" class="empty-state"><h3>Không tìm thấy buổi học</h3><button class="btn outline" @click="lessonSearch=''">Xóa tìm kiếm</button></div></template>
  <template v-else><div class="sentence-kpis"><div><span class="stat-icon green"><Icon name="BookOpen"/></span><strong>{{stats.learned}}<small>câu đã học qua</small></strong></div><div><span class="stat-icon blue"><Icon name="BadgeCheck"/></span><strong>{{stats.mastered}}<small>câu tự đánh giá nhớ vững</small></strong></div><div><span class="stat-icon purple"><Icon name="Layers"/></span><strong>{{stats.today_sentences}}<small>câu khác nhau đã luyện hôm nay</small></strong></div><div><span class="stat-icon orange"><Icon name="Flame"/></span><strong>{{stats.streak}}<small>ngày học câu liên tiếp</small></strong></div></div><section class="activity-card"><div class="section-heading"><div><h2>Nhịp học câu trong 7 ngày</h2><p>Gồm câu mới và câu ôn; mỗi câu chỉ tính một lần mỗi ngày.</p></div></div><div class="activity-chart sentence-chart"><div v-for="(day,i) in stats.activity" :key="day.day" class="chart-column"><strong>{{day.sentences}}</strong><div class="bar-slot"><span :class="{today:i===6}" :style="{height:Math.max(3,day.sentences/maxActivity*100)+'%'}"></span></div><small>{{i===6 ? 'Hôm nay' : day.day.slice(8)+'/'+day.day.slice(5,7)}}</small></div></div></section><div class="sentence-progress-grid"><section class="sentence-panel"><h2>Cách bạn đã luyện</h2><div v-for="[mode,label] in [['study','Nghe & hiểu'],['recall','Tự nhớ câu'],['response','Đáp lại tình huống']]" :key="mode" class="sentence-mode-stat"><span>{{label}}</span><strong>{{stats.modes.find(m=>m.mode===mode)?.total||0}} lượt</strong></div></section><section class="sentence-panel"><h2>Hiểu đúng tiến độ</h2><p class="sentence-explanation">“Đã học” là câu bạn đã tự đánh giá ít nhất một lần. “Nhớ vững” là đã tới mốc ôn 14 ngày hoặc hơn. Các con số phản ánh lịch ôn và tự đánh giá, không phải điểm chấm phát âm.</p><RouterLink :to="learn('study',{mode:'due',level:''})" class="btn outline">Ôn câu đến hạn<Icon name="ArrowRight" :size="16"/></RouterLink></section></div></template>
  </template>
  <div v-if="noteRow" class="modal-overlay" @click.self="noteRow=null"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="sentence-note-title"><div class="section-heading"><h2 id="sentence-note-title">Ghi chú cho {{noteRow.id}}</h2><button class="icon-button" aria-label="Đóng ghi chú" @click="noteRow=null"><Icon name="X"/></button></div><p class="muted">{{noteRow.english}}</p><form @submit.prevent="saveNote"><label>Liên hệ câu với cuộc sống của bạn<textarea v-model="noteText" maxlength="1500" rows="5" placeholder="Một tình huống bạn có thể dùng câu này…"></textarea></label><button class="btn primary full" :disabled="savingNote">{{savingNote?'Đang lưu…':'Lưu ghi chú'}}</button></form></section></div>
</div>
</template>
